node-ev-001.example:
```js
const { EventEmitter } = require('node:events');
const myEmitter = new EventEmitter();

// Register a listener; emit forwards all extra args to it.
myEmitter.on('event', (a, b) => console.log('got:', a, b));
myEmitter.emit('event', 'a', 'b'); // logs: got: a b
```

node-ev-mcq-001.example:
```js
const { EventEmitter } = require('node:events');
const e = new EventEmitter();

e.on('go', () => console.log('listener 1'));
e.on('go', () => console.log('listener 2'));
console.log('before emit');
e.emit('go');                 // runs both listeners synchronously, in order
console.log('after emit');    // only prints once both listeners finished
// Output: before emit, listener 1, listener 2, after emit
```

node-ev-mcq-002.example:
```js
const { EventEmitter } = require('node:events');
const myEmitter = new EventEmitter();

// ❌ Without this listener, emitting 'error' would throw and crash the process:
myEmitter.on('error', (err) => console.error('handled:', err.message));
myEmitter.emit('error', new Error('whoops!')); // logs: handled: whoops!
```

node-ev-002.example:
```js
const { EventEmitter } = require('node:events');
const e = new EventEmitter();

e.once('init', () => console.log('runs once only'));
e.emit('init'); e.emit('init'); // listener fired just the first time

function handler() { console.log('on every tick'); }
e.on('tick', handler);
e.emit('tick');
e.off('tick', handler);  // needs the SAME reference
e.emit('tick');          // no output — handler removed
```

node-ev-mcq-003.example:
```js
const { EventEmitter } = require('node:events');
const e = new EventEmitter();

// Adding 11 listeners for one event triggers the leak warning (default limit 10).
for (let i = 0; i < 11; i++) e.on('data', () => {});
console.log('listeners on "data":', e.listenerCount('data')); // 11
// Fix the duplicate registration, or e.setMaxListeners(20) if truly intended.
```

node-ev-003.example:
```js
const { EventEmitter } = require('node:events');
const e = new EventEmitter();

e.on('regular', function () {
  console.log('regular fn this === emitter:', this === e); // true
});
e.on('arrow', () => {
  console.log('arrow this === emitter:', this === e); // false (lexical this)
});
e.emit('regular');
e.emit('arrow');
```

node-ev-004.example:
```js
const { EventEmitter, once } = require('node:events');

async function main() {
  const e = new EventEmitter();
  setImmediate(() => e.emit('ready', 42)); // fire it soon so the await resolves
  const [value] = await once(e, 'ready');   // resolves with the emitted args
  console.log('awaited event value:', value); // 42
}
main();
```

node-fs-001.example:
```js
const { readFile } = require('node:fs/promises'); // promise style
const { readFile: readFileCb, readFileSync } = require('node:fs');

// 1) Promises
readFile(__filename, 'utf8').then((data) => console.log('promise:', data.length, 'chars'));
// 2) Callback (error-first)
readFileCb(__filename, 'utf8', (err, data) => console.log('callback:', err ?? data.length));
// 3) Sync (blocks)
console.log('sync:', readFileSync(__filename, 'utf8').length, 'chars');
```

node-fs-mcq-001.example:
```js
const http = require('node:http');
const { readFile } = require('node:fs/promises');

http.createServer(async (req, res) => {
  // ❌ readFileSync(__filename) here would block ALL other requests.
  // ✅ async read keeps the event loop free for concurrent requests:
  const data = await readFile(__filename, 'utf8');
  res.end(`file is ${data.length} chars`);
});
// (not calling .listen() so this snippet doesn't hold the process open)
```

node-fs-002.example:
